"""Build the transport paper on the reference (META University) template.

Usage: python3 -I build_transport.py <ref_unpacked_dir> <out_dir> <build_dir>
build_dir holds fig1.png, fig2.png and results.json (from model.py / figures.py).
"""
import copy, json, re, shutil, sys, os
from lxml import etree

REF, OUT, BD = sys.argv[1], sys.argv[2], sys.argv[3]
W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
W14 = 'http://schemas.microsoft.com/office/word/2010/wordml'
q = lambda t: '{%s}%s' % (W, t)
RES = json.load(open(f'{BD}/results.json'))

if os.path.exists(OUT):
    shutil.rmtree(OUT)
shutil.copytree(REF, OUT)
shutil.copy(f'{BD}/fig1.png', f'{OUT}/word/media/image2.png')
shutil.copy(f'{BD}/fig2.png', f'{OUT}/word/media/image3.png')

tree = etree.parse(f'{REF}/word/document.xml')
E = list(tree.getroot().find(q('body')))

# ---------------- helpers ----------------
def scrub(el):
    for x in el.iter():
        for a in list(x.attrib):
            if a.startswith('{%s}' % W14) or a.startswith('{%s}rsid' % W):
                del x.attrib[a]
    for tag in ('bookmarkStart', 'bookmarkEnd', 'lastRenderedPageBreak', 'proofErr'):
        for x in el.findall('.//' + q(tag)):
            x.getparent().remove(x)
    return el

def new_p(tmpl):
    p = etree.Element(q('p'))
    pp = tmpl.find(q('pPr'))
    if pp is not None:
        p.append(scrub(copy.deepcopy(pp)))
    return p

def mk_run(text, bold=None, sub=False, sup=False, italic=False):
    r = etree.Element(q('r'))
    rpr = etree.SubElement(r, q('rPr'))
    if bold is True:
        etree.SubElement(rpr, q('b')); etree.SubElement(rpr, q('bCs'))
    elif bold is False:
        etree.SubElement(rpr, q('b'), {q('val'): '0'}); etree.SubElement(rpr, q('bCs'), {q('val'): '0'})
    if italic:
        etree.SubElement(rpr, q('i')); etree.SubElement(rpr, q('iCs'))
    if sub or sup:
        etree.SubElement(rpr, q('vertAlign'), {q('val'): 'subscript' if sub else 'superscript'})
    if len(rpr) == 0:
        r.remove(rpr)
    if text == '\t':
        etree.SubElement(r, q('tab'))
        return r
    t = etree.SubElement(r, q('t')); t.text = text
    t.set('{http://www.w3.org/XML/1998/namespace}space', 'preserve')
    return r

TOK = re.compile(r'(\*\*.+?\*\*|~[^~]+~|\^[^^]+\^|\t)')
NBSP_RE = re.compile(r'(?<=\d) (?=\d{3}(?!\d))')
def add_text(p, text, bold=None):
    text = NBSP_RE.sub('\u00a0', text)
    for part in TOK.split(text):
        if not part:
            continue
        if part.startswith('**'):
            p.append(mk_run(part[2:-2], bold=True))
        elif part.startswith('~'):
            p.append(mk_run(part[1:-1], bold=bold, sub=True))
        elif part.startswith('^'):
            p.append(mk_run(part[1:-1], bold=bold, sup=True))
        else:
            p.append(mk_run(part, bold=bold))
    return p

body_out = []
emit = body_out.append

T_RUNIN, T_PARA, T_LIST_NUM, T_BUL, T_SPACER = E[82], E[99], E[87], E[120], E[111]
T_CAPTION, T_TABLE, T_AFTER_TABLE, T_FIG1, T_FIGCAP, T_FIG2 = E[114], E[115], E[116], E[129], E[130], E[192]
T_H1_PB, T_H2, T_H1_CONCL, T_REFS_H, T_REF = E[169], E[170], E[251], E[260], E[261]

def para(text):
    emit(add_text(new_p(T_PARA), text))

def runin(label, text, tmpl=T_RUNIN):
    p = new_p(tmpl); p.append(mk_run(label, bold=True)); p.append(mk_run(' '))
    emit(add_text(p, text))

def heading_runin(tmpl, label, text):
    p = new_p(tmpl); p.append(mk_run(label)); p.append(mk_run(' '))
    emit(add_text(p, text, bold=False))

def heading(tmpl, text):
    emit(add_text(new_p(tmpl), text))

NUM_IDS = iter(str(i) for i in range(20, 30))
def numbered(items):
    nid = next(NUM_IDS)
    for it in items:
        p = new_p(T_LIST_NUM)
        p.find('.//' + q('numId')).set(q('val'), nid)
        emit(add_text(p, it))

def bullets(items):
    for it in items:
        emit(add_text(new_p(T_BUL), it))

def spacer():
    emit(new_p(T_SPACER))

def caption(text):
    emit(add_text(new_p(T_CAPTION), text))

def formula(text, n):
    p = etree.Element(q('p'))
    ppr = etree.SubElement(p, q('pPr'))
    tabs = etree.SubElement(ppr, q('tabs'))
    etree.SubElement(tabs, q('tab'), {q('val'): 'center', q('pos'): '4678'})
    etree.SubElement(tabs, q('tab'), {q('val'): 'right', q('pos'): '9355'})
    etree.SubElement(ppr, q('spacing'), {q('before'): '60', q('after'): '60'})
    etree.SubElement(ppr, q('ind'), {q('firstLine'): '0'})
    emit(add_text(p, f'\t{text}\t({n})'))

TBL_ROWS = T_TABLE.findall(q('tr'))
def table(widths, rows, center_cols=(0,)):
    t = etree.Element(q('tbl'))
    tblpr = scrub(copy.deepcopy(T_TABLE.find(q('tblPr'))))
    t.append(tblpr)
    grid = etree.SubElement(t, q('tblGrid'))
    for w in widths:
        etree.SubElement(grid, q('gridCol'), {q('w'): str(w)})
    for ri, row in enumerate(rows):
        src_tr = TBL_ROWS[0] if ri == 0 else TBL_ROWS[1]
        tr = etree.SubElement(t, q('tr'))
        tr.append(scrub(copy.deepcopy(src_tr.find(q('trPr')))))
        src_tcs = src_tr.findall(q('tc'))
        for ci, (w, text) in enumerate(zip(widths, row)):
            src_tc = src_tcs[0] if (ri == 0 or ci in center_cols) else src_tcs[1]
            tc = scrub(copy.deepcopy(src_tc))
            tc.find(q('tcPr')).find(q('tcW')).set(q('w'), str(w))
            p0 = tc.find(q('p'))
            for r in p0.findall(q('r')):
                p0.remove(r)
            add_text(p0, text, bold=True if ri == 0 else None)
            tr.append(tc)
    emit(t)
    emit(new_p(T_AFTER_TABLE))

def figure(tmpl, cap, ratio=None):
    p = scrub(copy.deepcopy(tmpl))
    if ratio:
        for tag in ('{http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing}extent',
                    '{http://schemas.openxmlformats.org/drawingml/2006/main}ext'):
            for e in p.iter(tag):
                e.set('cy', str(int(int(e.get('cx')) * ratio)))
    emit(p)
    emit(add_text(new_p(T_FIGCAP), cap))

def fmt(x, nd=1):
    s = f'{x:,.{nd}f}'.replace(',', '\u00a0').replace('.', ',')
    return s

# ---------------- cover ----------------
def set_runs_text(p, text, keep_first_run=False):
    runs = p.findall(q('r'))
    if keep_first_run:
        for r in runs[1:]:
            p.remove(r)
        p.append(mk_run(' '))
        add_text(p, text)
        return
    first = True
    for r in runs:
        for t in r.findall(q('t')):
            if first:
                t.text = text; first = False
            else:
                r.remove(t)
    assert not first, text

OLD_MAIL, NEW_MAIL = 'a.sartai@meta.edu.kz', 'b.sabitov@meta.edu.kz'
for e in E[0:41]:
    el = scrub(copy.deepcopy(e))
    s = ''.join(el.itertext())
    if s.startswith('тақырыбы:'):
        set_runs_text(el, 'тақырыбы: «Көлік жүйесін жобалау және жүктеме моделін құру»')
    elif s.startswith('Орындаған:'):
        set_runs_text(el, 'Орындаған: Сабитов Б.')
    emit(el)

